// The C# conformance case runner (docs/CONFORMANCE.md §2). Compiled into the harness host; the
// per-directory harness generated by the adapter (conformance.ts) passes its roots to Runner.Run.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Yaffle.Runtime;

namespace Yaffle.Harness;

/// <summary>The entry points of one root, as untyped delegates.</summary>
public sealed class RootEntry
{
    public required Func<JsonNode?, ParseOptions> Options { get; init; }
    public required Func<byte[], ParseOptions, object> Parse { get; init; }
    public required Func<object, JsonNode> ToJson { get; init; }
    public required Func<JsonNode?, object> FromJson { get; init; }
    public required Func<object, ParseOptions, byte[]> Serialize { get; init; }
    /// <summary>Opens a lazy view over bytes, or over a file source when the path is given (view mode).</summary>
    public required Func<byte[], string?, ParseOptions, ViewHandle> View { get; init; }
}

/// <summary>A view opened by the harness: canonical JSON read through it, and commits with no edits.</summary>
public sealed class ViewHandle : IDisposable
{
    public required Func<JsonNode> Json { get; init; }
    public required Func<byte[]> Commit { get; init; }
    /// <summary>The patches of a forced re-serialization (the structural commit path).</summary>
    public required Func<IReadOnlyList<Patch>> Rewrite { get; init; }
    public IDisposable? Resource { get; init; }

    public void Dispose() => Resource?.Dispose();
}

public static class Runner
{
    /// <summary>Byte outputs larger than this are left out of results (large sample files).</summary>
    private const int MaxHexBytes = 1 << 20;

    /// <summary>
    /// Runs every case of <paramref name="casesFile"/> and writes result k to
    /// <c><paramref name="resultsDir"/>/k.json</c> (one file per case: large samples give large results).
    /// </summary>
    public static void Run(IReadOnlyDictionary<string, RootEntry> roots, string casesFile, string resultsDir, string mode)
    {
        bool view = mode == "view";
        var cases = Json.Parse(File.ReadAllText(casesFile))!.AsArray();
        Directory.CreateDirectory(resultsDir);
        int k = 0;
        foreach (var c in cases)
        {
            var co = c!.AsObject();
            var name = co["name"]!.GetValue<string>();
            var rootName = co["root"]!.GetValue<string>();
            JsonObject r;
            if (!roots.TryGetValue(rootName, out var entry))
                r = new JsonObject { ["name"] = name, ["ok"] = false, ["message"] = $"unknown root {rootName}" };
            else
            {
                try
                {
                    r = RunCase(co, name, entry, view);
                }
                catch (Exception e)
                {
                    r = new JsonObject { ["name"] = name, ["ok"] = false, ["message"] = $"harness failure: {e}" };
                }
            }
            using var w = new StreamWriter(Path.Combine(resultsDir, $"{k++}.json"), false, new UTF8Encoding(false), 1 << 20);
            Json.WriteTo(r, w);
        }
    }

    private static bool NotImplemented(string msg) =>
        msg.Contains("not implemented", StringComparison.OrdinalIgnoreCase) || msg.Contains("not supported", StringComparison.OrdinalIgnoreCase);

    private static string Hex(byte[] b) => Convert.ToHexStringLower(b);

    /// <summary>"json", "value" or "false": how a parse case round-trips (an expected serialize error implies "json").</summary>
    private static string RoundTripMode(JsonObject c, string? expPhase)
    {
        if (expPhase == "serialize" || !c.TryGetPropertyValue("roundtrip", out var rt) || rt is null) return "json";
        return rt.GetValueKind() switch
        {
            JsonValueKind.False => "false",
            JsonValueKind.True => "json",
            _ => rt.GetValue<string>()
        };
    }

    /// <summary>Null when the bytes are equal, else what differs.</summary>
    private static string? Difference(string what, byte[] expected, byte[] got)
    {
        if (got.AsSpan().SequenceEqual(expected)) return null;
        int i = 0;
        while (i < got.Length && i < expected.Length && got[i] == expected[i]) i++;
        return $"{what}: bytes differ at offset 0x{i:x} (expected {expected.Length} bytes, got {got.Length})";
    }

    private static JsonObject RunCase(JsonObject c, string name, RootEntry api, bool view)
    {
        var result = new JsonObject { ["name"] = name, ["ok"] = false };
        JsonObject Done(bool ok, string? message = null)
        {
            result["ok"] = ok;
            if (message is not null) result["message"] = message;
            return result;
        }
        void SetBytes(byte[] o)
        {
            if (o.Length <= MaxHexBytes) result["bytes"] = Hex(o);
        }
        var expected = c["error"] as JsonObject;
        string? expPhase = expected?["phase"]?.GetValue<string>();
        string? expCode = expected?["code"]?.GetValue<string>();
        bool hasInput = c.TryGetPropertyValue("input", out var input);
        bool hasJson = c.TryGetPropertyValue("json", out var expJson);
        string phase = hasInput ? "serialize" : "parse";
        byte[]? bytes = null;
        string? file = null;
        if (c["bytes"] is JsonNode b)
        {
            if (b is JsonValue) bytes = Convert.FromHexString(b.GetValue<string>());
            else
            {
                file = b["file"]!.GetValue<string>();
                bytes = File.ReadAllBytes(file);
            }
        }
        try
        {
            var options = api.Options(c["args"]);
            if (c["strict"] is JsonNode st && st.GetValue<bool>()) options.Strict = true;
            if (hasInput)
            {
                var o = api.Serialize(api.FromJson(input), options);
                SetBytes(o);
                if (expected is not null) return Done(false, $"expected {expCode}, but serialize succeeded");
                if (bytes is null) return Done(false, "serialize case without bytes");
                if (!o.AsSpan().SequenceEqual(bytes))
                    return Done(false, $"serialize: expected {Hex(bytes)}, got {(o.Length <= MaxHexBytes ? Hex(o) : "(large)")}");
                return Done(true);
            }
            if (bytes is null) return Done(false, "parse case without bytes");
            string rt = RoundTripMode(c, expPhase);
            if (view)
            {
                // View mode (docs/CONFORMANCE.md §7): every field is read through the lazy view, a
                // forced re-serialization of the unedited view gives no patches, and a commit with no
                // edits reproduces the input.
                using var h = api.View(bytes, file, options);
                result["json"] = h.Json();
                if (expPhase == "parse") return Done(false, $"expected {expCode}, but reading the view succeeded");
                if (rt == "false") return Done(true);
                phase = "serialize";
                var patches = h.Rewrite();
                if (patches.Count > 0)
                {
                    var p0 = patches[0];
                    return Done(false, $"rewrite: {patches.Count} patches for an unedited view, the first at 0x{p0.At:x} (remove {p0.Remove}, insert {p0.Insert.Length})");
                }
                var committed = h.Commit();
                SetBytes(committed);
                if (expPhase == "serialize") return Done(false, $"expected {expCode}, but the commit succeeded");
                var commitDiff = Difference("commit", bytes, committed);
                return commitDiff is null ? Done(true) : Done(false, commitDiff);
            }
            var value = api.Parse(bytes, options);
            var json = api.ToJson(value);
            result["json"] = json;
            if (expPhase == "parse") return Done(false, $"expected {expCode}, but parse succeeded");
            if (rt == "false") return Done(true);
            phase = "serialize";
            var output = api.Serialize(rt == "value" ? value : api.FromJson(hasJson ? expJson : json), options);
            SetBytes(output);
            if (expPhase == "serialize") return Done(false, $"expected {expCode}, but serialize succeeded");
            var diff = Difference("roundtrip", bytes, output);
            return diff is null ? Done(true) : Done(false, diff);
        }
        catch (YaffleException e)
        {
            var path = new JsonArray(e.Path.Select(seg => seg is string s ? JsonValue.Create(s) : (JsonNode)JsonValue.Create(Convert.ToInt64(seg, System.Globalization.CultureInfo.InvariantCulture))).ToArray());
            result["error"] = new JsonObject
            {
                ["phase"] = phase,
                ["code"] = e.Code.ToString(),
                ["path"] = path,
                ["offset"] = e.Offset,
                ["message"] = e.Message
            };
            if (expected is null)
            {
                if (NotImplemented(e.Message)) result["skipped"] = e.Message;
                return Done(false, $"unexpected {e.Code} error in {phase}: {e.Message}");
            }
            if (expPhase != phase) return Done(false, $"expected a {expPhase} error, got {e.Code} in {phase}: {e.Message}");
            if (expCode != e.Code.ToString()) return Done(false, $"expected {expCode}, got {e.Code}: {e.Message}");
            if (expected["path"] is JsonArray ep && ep.ToJsonString() != path.ToJsonString())
                return Done(false, $"expected path {ep.ToJsonString()}, got {path.ToJsonString()} ({e.Message})");
            return Done(true);
        }
        catch (Exception e)
        {
            if (!NotImplemented(e.Message)) return Done(false, $"unexpected exception in {phase}: {e}");
            result["skipped"] = e.Message;
            return Done(false, e.Message);
        }
    }
}
